/** @requirements REQ-PRODUCT-CONTRACT-ACTIONS Receipt, provider acceptance and fulfillment stay distinct. */
function contractSummary(record:EvidenceRecord):string|undefined {
 const d=objectData(record.data);if(d.kind!=='contract-declaration')return undefined;
 return storedText(objectData(objectData(d.definition).wording).title,'Contract declaration')+' · '+storedText(objectData(objectData(d.request).fields).name,'Visitor-provided name');
}
