function contractPanel(record:EvidenceRecord):string {
 if(!contractSummary(record))return '';const d=objectData(record.data),definition=objectData(d.definition),wording=objectData(definition.wording),request=objectData(d.request),f=objectData(request.fields),c=objectData(f.cancellation),receipt=objectData(d.receipt),ack=objectData(receipt.acknowledgement),jobs=objectData(d.delivery);
 return `<section class="card"><h2>Declaration details</h2><p class="notice">Visitor-provided claims, received by the host. Receipt, confirmation delivery and application fulfillment are separate.</p><div class="detail-grid">${[['acknowledgement','Electronic acknowledgement'],['application','Application handoff']].map(([channel,title])=>{const job=objectData(jobs[channel!]);return `<section class="card"><h3>${escapeHtml(title!)}</h3><p class="detail-value">${escapeHtml(contractDeliveryStatus(job))}</p><p class="hint">${escapeHtml(storedText(job.attempts))} attempt${job.attempts===1?'':'s'} · ${readableTime(job.updatedAt)}</p><p class="hint">${channel==='acknowledgement'?'Must run independently of contract matching. Provider acceptance does not prove recipient delivery.':'No cancellation, refund or effective end date is inferred from this handoff.'}</p></section>`;}).join('')}</div><div class="agreement-statement"><h3>Exact declaration</h3><p>${escapeHtml(storedText(wording.statement))}</p><h3>Final action shown</h3><p>${escapeHtml(storedText(wording.confirmLabel))}</p></div>${facts([['Visitor-provided name',f.name],['Contract or part identified',f.contract],['Confirmation address',f.email],['Cancellation type',c.kind],['Reason supplied',c.reason],['Requested ending',f.cancellation===undefined?undefined:c.ending||'Earliest possible'],['Host receipt time',d.occurredAt],['Browser-reported time (unverified)',request.clientAt]])}<details class="record-references"><summary>Exact savable acknowledgement and references</summary><pre tabindex="0">${escapeHtml(storedText(ack.text))}</pre>${facts([['Action definition',definition.definitionId],['Form revision',definition.revision],['Profile',definition.profile],['Request ID',request.requestId],['Request SHA-256',receipt.requestSha256],['Acknowledgement SHA-256',ack.sha256],['Application delivery ID',objectData(jobs.application).deliveryId],['Confirmation delivery ID',objectData(jobs.acknowledgement).deliveryId]])}</details><p class="footnote">Archived form documents do not establish the terms governing the original contract. The host owns admission, prompt dispatch, contract/identity matching, eligibility, fulfillment, retention and external copies.</p></section>`;
}
/** @requirements REQ-PRODUCT-FORM-PERMISSIONS Historical assertion and evaluated current permission stay distinct. */
