function permissionStateLabel(value:JsonValue|undefined):string {const state=objectData(value);if(state.permitted===true)return 'Allowed';return ({withdrawn:'Withdrawn','offer-changed':'Needs a new choice',inactive:'Unavailable','scope-restricted':'Separate process required','not-granted':'Not granted'} as Record<string,string>)[String(state.reason)]??'Not evaluated';}
